question.answer:
from abc import ABC, abstractmethod
from collections.abc import Iterable


class CheckFailed(Exception):
    """Raised when a safety check rejects a reading."""


class SafetyCheck(ABC):
    def __init__(self, name: str) -> None:
        self.name = name
        self.failures: list[float] = []

    @abstractmethod
    def evaluate(self, reading: float) -> bool:
        """Return True when the reading is acceptable."""

    @abstractmethod
    def describe(self) -> str:
        """Return one line of text describing this check."""

    def failure_error(self, reading: float) -> CheckFailed:
        return CheckFailed(f"{self.name} rejected {reading}")

    def run(self, reading: float) -> str:
        if self.evaluate(reading):
            return f"{self.name} accepted {reading}"
        self.failures.append(reading)
        raise self.failure_error(reading)


def report(checks: Iterable[SafetyCheck]) -> str:
    return " | ".join(check.describe() for check in checks)


class OutOfRange(CheckFailed):
    """Raised when a reading sits outside the allowed band."""


class RangeCheck(SafetyCheck):
    def __init__(self, name: str, low: float, high: float) -> None:
        super().__init__(name)
        self.low = low
        self.high = high

    def evaluate(self, reading: float) -> bool:
        return self.low <= reading <= self.high

    def describe(self) -> str:
        return f"{self.name} keeps readings in {self.low}..{self.high}"

    def failure_error(self, reading: float) -> CheckFailed:
        return OutOfRange(f"{self.name} rejected {reading} outside {self.low}..{self.high}")


class RateOfChangeCheck(SafetyCheck):
    def __init__(self, name: str, limit: float) -> None:
        super().__init__(name)
        self.limit = limit
        self.previous: float | None = None

    def evaluate(self, reading: float) -> bool:
        if self.previous is None:
            self.previous = reading
            return True
        jump = abs(reading - self.previous)
        self.previous = reading
        return jump <= self.limit

    def describe(self) -> str:
        return f"{self.name} allows jumps up to {self.limit}"


def abstract_error() -> str:
    try:
        SafetyCheck("base")
    except TypeError as problem:
        return f"TypeError and the word abstract appears: {'abstract' in str(problem)}"
    return "no error"

