question.answer:
from typing import Self, override


class Sensor:
    def __init__(self, name: str, value: float) -> None:
        self.name = name
        self.value = value

    def describe(self) -> str:
        return f"{self.name}={self.value}"

    def calibrate(self, offset: float) -> Self:
        return type(self)(self.name, self.value + offset)

    @classmethod
    def from_text(cls, text: str) -> Self:
        name, _, raw = text.partition("=")
        return cls(name, float(raw))


class PressureSensor(Sensor):
    @override
    def describe(self) -> str:
        return f"pressure {self.name} at {self.value:.1f} bar"


class TemperatureSensor(Sensor):
    @override
    def describe(self) -> str:
        return f"temperature {self.name} at {self.value:.1f} C"


class RelaySensor(Sensor):
    @override
    def calibrate(self, offset: float) -> Self:
        return type(self)(self.name, self.value + offset * 2)

